function assignmentRoleMetadata_(role,row,labor){
 const inferred=/^HW\b/i.test(role)?'HW':/^ประชุมวิชาการ/.test(role)?'วิชาการ':/^PN\b/.test(role)?'PN':/^NA\b/.test(role)?'NA':/^พนง/.test(role)?'พนง':'RN';
 const staffType=String(row['ประเภทบุคลากร']||row.staffType||inferred),raw=row['นับพยาบาล']??row.counted;
 const counted=raw===undefined||raw===''?staffType==='RN':toBool_(raw);
 const fixedTeam=labor?({'สูติ AB Incharge':'AB','สูติ AB Member1':'AB','สูติ AB Member2':'AB','รับใหม่':'AB','ทำคลอด':'LABOR','รับเด็ก':'LABOR','อาบน้ำเด็ก':'LABOR'})[role]:undefined;
 return {staffType:staffType,counted:counted,npTeam:fixedTeam||String(row['ทีม NP']||row.npTeam||'NONE')};
}

