function p4pActualDate_(claimDate,shift){return shift==='เวรดึก'?p4pShiftDate_(claimDate,1):String(claimDate).slice(0,10);}

function p4pAutoPer_(a,x){if(x.fixedPer)return Number(x.fixedPer);const quantity=Number(x.quantity||0),divisor=Number(x.divisor||0),unit=Number(a.minutes||0)*Number(a.point||0);if(p4pWholePatientType_(a))return x.each?Math.floor(quantity+1e-9)*unit:divisor>0?Math.floor(quantity/divisor+1e-9)*unit:0;return quantity*unit*(x.each?1:(divisor>0?1/divisor:0));}


function p4pClaimDate_(date,shift){return shift==='เวรดึก'?p4pShiftDate_(date,-1):String(date).slice(0,10);}

function p4pDailyMatrixCss_(){return `
@page dailyMatrix{size:A4 landscape;margin:6mm}
.dailyMatrixPage{position:relative;width:285mm;max-width:100%;break-inside:avoid;page-break-inside:avoid;page:dailyMatrix;color:#000;font-family:Tahoma,Arial,sans-serif;page-break-before:always}
.dailyMatrixPage:first-child{page-break-before:auto}
.p4pFitContent{display:flow-root;position:static;break-inside:avoid;page-break-inside:avoid}
.dailyMatrixPage .dailyMatrix,.headMatrix> .p4pFitContent>table,.headSummary> .p4pFitContent>table{break-inside:avoid;page-break-inside:avoid}
@media print{.dailyMatrixPage thead,.headMatrix thead,.headSummary thead{display:table-row-group}}
.dailyMatrixPage .matrixTitle{font-size:7pt;text-align:center;font-weight:bold;margin:0 0 3mm;line-height:1.3}
.dailyMatrixPage .matrixNote{font-size:5.5pt;text-align:center;margin:0 0 2mm;color:#333}
.dailyMatrixPage .dailyMatrix{width:100%;table-layout:fixed;border-collapse:collapse;font-size:5.8pt;color:#000}
.dailyMatrixPage .dailyMatrix th,.dailyMatrixPage .dailyMatrix td{border:0.4pt solid #000;padding:1pt .7pt;line-height:1.12;text-align:center!important;overflow-wrap:anywhere;vertical-align:middle}
.dailyMatrixPage .dailyMatrix thead th{background:#d4e6f3;font-weight:normal}
.dailyMatrixPage .dailyMatrix td.activityLabel{text-align:left!important}
.dailyMatrixPage .dailyMatrix .matrixSection td{background:#fff1cb;font-weight:bold;text-align:left!important}
.dailyMatrixPage .dailyMatrix .matrixQuantity{background:#e0edf6}
.dailyMatrixPage .dailyMatrix .matrixInfo td{font-size:5.3pt;color:#444}
.dailyMatrixPage .matrixPageNumber{font-size:5pt;text-align:right;margin-top:1mm}
@media print{body{margin:0}.dailyMatrixPage{width:285mm;max-width:none}}
`;}

