function p4pHeadValidate_(month,entries){
 const count=new Date(Number(month.slice(0,4)),Number(month.slice(5,7)),0).getDate(),catalog=new Map(p4pHeadCatalog_().map(a=>[a.id,a])),seen=new Set(),totals={},output=[];
 if(!Array.isArray(entries)||entries.length>catalog.size*count)throw new Error('รายการภาระงานไม่ถูกต้อง');
 entries.forEach(e=>{const a=catalog.get(String(e.activityId)),day=Number(e.day),key=day+'|'+String(e.activityId);if(!a||!Number.isInteger(day)||day<1||day>count||seen.has(key))throw new Error('กิจกรรม/วันที่ซ้ำหรือไม่ถูกต้อง');seen.add(key);const score=p4pHeadEntryScore_(a,e),quantity=Number(e.quantity||0),note=String(e.note||'').trim();if(note.length>500)throw new Error('หมายเหตุยาวเกิน 500 ตัวอักษร');if(quantity===0)return;totals[a.id]=(totals[a.id]||0)+quantity;output.push({activityId:a.id,day,quantity,minutes:a.actual?(e.minutes==null||e.minutes===''?a.minutes:Number(e.minutes)):null,note,score});});
 catalog.forEach(a=>{if(a.maxMonth&&Number(totals[a.id]||0)>a.maxMonth)throw new Error(a.name+' เบิกได้ไม่เกิน '+a.maxMonth+' ครั้ง/เดือน');});
 if((totals.HA19A||0)+(totals.HA19B||0)>1)throw new Error('รายงานสถิติประจำเดือนเลือกส่งทันเวลาหรือเกินเวลา รวมไม่เกิน 1 ครั้ง/เดือน');return output;
}

