function p4pSupportCss_(){return `
@font-face{font-family:P4PSarabun;src:url(data:font/ttf;base64,)}
.supportPersonal,.supportSummary{font-family:P4PSarabun,Tahoma,sans-serif}
@page supportPersonal{size:A4 landscape;margin:6mm}@page supportSummary{size:A4 portrait;margin:6mm}
.supportPersonal{page:supportPersonal;color:#000;position:relative;width:285mm;max-width:100%;break-inside:avoid;page-break-inside:avoid}.supportSummary{page:supportSummary;color:#000;position:relative;width:198mm;max-width:100%;break-inside:avoid;page-break-inside:avoid}
@media print{.supportPersonal{width:285mm;max-width:none}.supportSummary{width:198mm;max-width:none}.supportPersonal thead,.supportSummary thead{display:table-row-group}}
.supportPageNumber{text-align:right;font-size:7pt;margin:4pt 0}.supportMeta{text-align:center;font-size:8.5pt;line-height:1.5;margin:0 0 3pt}
.supportActivityTable{width:100%;table-layout:fixed;border-collapse:collapse;font-size:8.2pt}
.supportActivityTable th,.supportActivityTable td{border:.5pt solid #555;padding:0 1pt;height:15pt;line-height:1.15;text-align:center;overflow-wrap:anywhere;white-space:normal}
.supportActivityTable .supportHeader th{height:22pt;font-size:10pt}.supportActivityTable .supportHeaderBlue{background:#dceef2}.supportActivityTable .supportHeaderScore{color:#d00;font-weight:normal;white-space:nowrap}.supportDraft{text-align:center;color:#b66b00;font-size:9pt}.supportActivityTable th{background:white}.supportActivityTable td.supportActivity{font-size:7.3pt;text-align:left;white-space:normal}
.supportActivityTable .supportSection td{text-align:left;font-weight:bold;background:#d8eaf2;height:15pt}
.supportActivityTable .supportShifts td{background:#eef6f9;font-size:7pt}.supportActivityTable .supportGrandTotal td{font-weight:bold;text-align:right}.supportActivityTable .supportGrandTotal td:last-child{white-space:nowrap;overflow-wrap:normal;padding-right:3pt;font-variant-numeric:tabular-nums}
.supportPersonal .individualSignatures{font-size:8pt!important;margin-top:5pt!important}.supportPersonal .individualSignatures td{padding:1pt!important;text-align:center!important;border:0!important;line-height:1.2}
.supportPersonal .individualSignatures td>div:first-child{height:24px!important}.supportPersonal .individualSignatures img{height:23px!important;max-width:140px!important}.supportPersonal .individualSignatures small{font-size:6pt!important}
.supportSummary table{font-size:11.5pt;table-layout:fixed}.supportSummary th,.supportSummary td{border:.6pt solid #222;padding:3pt 3pt;line-height:1.15}.supportSummary th{background:white;text-align:center}.supportSummary thead tr:last-child th:first-child{font-size:10pt;white-space:nowrap}.supportSummary td{text-align:left}.supportSummary td:nth-child(1){text-align:center}.supportSummary td:nth-child(4),.supportSummary td:nth-child(5){text-align:right;white-space:nowrap}.supportSummary thead tr:last-child th{white-space:nowrap}
.supportSummary .supportSummaryTotal td{font-weight:bold}.supportSummary .supportSummaryTotal td:nth-child(3){text-align:right}.supportSummary .supportSummarySigns{margin-top:18mm;border:0}.supportSummary .supportSummarySigns td{border:0;text-align:center!important;padding:5pt 0}
`;}


