 return{pages,sheet:{name:r.group==='PN'?'สรุป PN':'สรุป NA และ พนง',widths:[8,32,28,18,18,24],rows:[[title+' ประจำเดือน '+period],['หน่วยงาน','',ward],['แต้มประกัน','',r.guarantee],headers,[],...rows,['สรุปจำนวนเจ้าหน้าที่ (คน)','',rows.length,{t:'n',f:'SUM(D6:D'+(rows.length+5)+')',v:roundP4PReport_(total),z:'#,##0.00'},{t:'n',f:'SUM(E6:E'+(rows.length+5)+')',v:roundP4PReport_(excess),z:'#,##0.00'},'']],merges:[{s:{r:0,c:0},e:{r:0,c:5}},{s:{r:1,c:0},e:{r:1,c:1}},{s:{r:1,c:2},e:{r:1,c:5}},{s:{r:2,c:0},e:{r:2,c:1}},{s:{r:2,c:2},e:{r:2,c:5}},...Array.from({length:6},(_,c)=>({s:{r:3,c},e:{r:4,c}})),{s:{r:rows.length+5,c:0},e:{r:rows.length+5,c:1}}]}};
