function p4pSupportUnit_(a){const n=Number(a.id.split('_')[1]),g=a.group;if((g==='PN'&&n===48)||(g==='NA'&&n===47)||(g==='EMP'&&n===46))return 'แฟ้ม';if(g==='EMP'&&n===30)return 'เตียง';if(g==='EMP'&&n===31)return 'ห้อง';if((g==='PN'&&n===33)||(g==='NA'&&n===32))return 'เวร';if(/รับ-ส่งเวร|ชั่งน้ำหนัก|ช่วยเปลี่ยนชุด|OK|Set|CSS|ล้าง|ทำความสะอาดสถานที่|ดูแลอุปกรณ์|ประสาน|เบิก|ส่งซ่อม|ส่ง ซ่อม|เก็บ|รวบรวม|กิจกรรมวัน|ประชุม|เช็ดถู|บานเกล็ด|สิ่งแวดล้อม|รับส่งอุปกรณ์|ส่งวัสดุ/.test(a.name))return 'ครั้ง';return 'ราย';}

function p4pUnitSummaryCss_(){return `
@page unitSummary{size:A4 portrait;margin:9mm}
.unitSummaryPage{page:unitSummary;color:#000;font-family:Tahoma,Arial,sans-serif;font-size:8pt;page-break-before:always}
.unitSummaryPage:first-child{page-break-before:auto}
.unitSummaryPage .unitSummaryTitle{text-align:center;font-size:9pt;font-weight:bold;margin:0 0 4mm}
.unitSummaryPage .unitSummaryTable{width:100%;table-layout:fixed;border-collapse:collapse;color:#000;font-size:7.5pt}
.unitSummaryPage .unitSummaryTable th,.unitSummaryPage .unitSummaryTable td{border:.5pt solid #000;line-height:1.35;padding:4pt 2pt;vertical-align:middle;text-align:center!important;overflow-wrap:break-word}
.unitSummaryPage .unitSummaryTable th{background:#fff;font-weight:bold}
.unitSummaryPage .unitSummaryTable .unitSummaryMeta th{background:#ddd}
.unitSummaryPage .unitSummaryTable .unitName,.unitSummaryPage .unitSummaryTable .unitPosition{text-align:left!important}
.unitSummaryPage .unitSummaryTable .unitSummaryTotals td{font-weight:bold}
.unitSummaryPage .unitSummarySign{margin-top:9mm;width:100%;border:0;table-layout:fixed;font-size:9pt}
.unitSummaryPage .unitSummarySign td{border:0!important;text-align:center!important;padding:3pt;line-height:1.5}
.unitSummaryPage .unitDraft{text-align:center;font-size:8pt;color:#955400;margin:0 0 3mm}
`;}

function p4pUnitSummary_(r,ward,period){
 const e=escapeHtml_,round=roundP4PReport_,num=v=>Number(v||0).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2}),staff=(r.staff||[]).map(p=>p.noClaim?{...p,administration:0,service:0,academic:0,total:0,excess:0}:p),pages=[],limit=24,guarantee=Number(r.guarantee||0),columns=['ลำดับ','ชื่อ-สกุล','ตำแหน่ง','บริหาร','บริการ','วิชาการ','แต้มรวม','แต้มเกิน','หมายเหตุ'],rows=[],merges=[];
 const note=p=>p.noClaim?'ไม่เบิกเดือนนี้ — '+p.claimRemark:p.claimRemark||(p.bonus?num(p.bonus):''),position=p=>p.position||'พยาบาลวิชาชีพ',total=key=>round(staff.reduce((v,p)=>v+Number(p[key]||0),0));
 const excel=[['สรุปแต้มพยาบาล กลุ่มภารกิจด้านการพยาบาลโรงพยาบาลวชิระภูเก็ต (เอกสารหมายเลข 3)'],['หน่วยงาน',ward,'','','ประจำเดือน',period],['แต้มประกัน',guarantee,'','หัวหน้าหอแต้มต่อบริหาร 30%',round(guarantee*.3)],['','','','ผู้ตรวจแต้มต่อ 15%',round(guarantee*.15)],columns];
 merges.push({s:{r:0,c:0},e:{r:0,c:8}});staff.forEach((p,i)=>excel.push([i+1,p.displayName,position(p),round(p.administration),round(p.service),round(p.academic),round(p.total),round(p.excess),note(p)]));excel.push(['สรุปจำนวนเจ้าหน้าที่ (ทั้งหมดในรายงาน) (คน)',staff.length,'',total('administration'),total('service'),total('academic'),total('total'),total('excess'),'']);
 for(let start=0;start<Math.max(staff.length,1);start+=limit){const last=start+limit>=staff.length,chunk=staff.slice(start,start+limit),body=chunk.map((p,i)=>'<tr><td>'+(start+i+1)+'</td><td class="unitName">'+e(p.displayName)+'</td><td class="unitPosition">'+e(position(p))+'</td>'+[p.administration,p.service,p.academic,p.total,p.excess].map(v=>'<td>'+num(v)+'</td>').join('')+'<td>'+e(note(p))+'</td></tr>').join('');
  const sum=last?'<tr class="unitSummaryTotals"><td colspan="3">สรุปจำนวนเจ้าหน้าที่ (ทั้งหมดในรายงาน) (คน)</td><td colspan="3">'+staff.length+'</td><td>'+num(total('total'))+'</td><td>'+num(total('excess'))+'</td><td></td></tr>':'';
  pages.push('<section class="unitSummaryPage"><div class="unitSummaryTitle">สรุปแต้มพยาบาล กลุ่มภารกิจด้านการพยาบาลโรงพยาบาลวชิระภูเก็ต (เอกสารหมายเลข 3)</div>'+(r.draft?'<p class="unitDraft">ฉบับร่าง</p>':'')+'<table class="unitSummaryTable"><colgroup>'+[5,21,23,8.5,8.5,8.5,9,9,7.5].map(w=>'<col style="width:'+w+'%">').join('')+'</colgroup><thead><tr class="unitSummaryMeta"><th colspan="3">หน่วยงาน '+e(ward)+'</th><th colspan="3">ประจำเดือน</th><th colspan="3">'+e(period)+'</th></tr><tr><th colspan="3">แต้มประกัน '+num(guarantee)+'</th><th colspan="6">หมายเหตุ หัวหน้าหอแต้มต่อบริหาร 30% = '+num(guarantee*.3)+'</th></tr><tr><th colspan="3"></th><th colspan="6">ผู้ตรวจแต้มต่อ 15% = '+num(guarantee*.15)+'</th></tr><tr><th rowspan="2">ลำดับ</th><th rowspan="2">ชื่อ-สกุล</th><th rowspan="2">ตำแหน่ง</th><th colspan="3">ประเภทกิจกรรม</th><th rowspan="2">แต้มรวม</th><th rowspan="2">แต้มเกิน</th><th rowspan="2">หมายเหตุ</th></tr><tr><th>บริหาร</th><th>บริการ</th><th>วิชาการ</th></tr></thead><tbody>'+body+sum+'</tbody></table>'+(last?'<table class="unitSummarySign"><tr><td>ลงชื่อ ................................................</td><td>ลงชื่อ ................................................</td></tr><tr><td>( '+e(r.supervisorName||'........................................')+' )</td><td>( ........................................ )</td></tr><tr><td>หัวหน้าหอผู้ป่วย '+e(ward)+'</td><td>ผู้ตรวจสอบ</td></tr></table>':'')+'<p style="text-align:right;font-size:7pt;margin-top:3mm">หน้า '+(Math.floor(start/limit)+1)+' / '+Math.max(1,Math.ceil(staff.length/limit))+'</p></section>');
 }return{pages,sheet:{name:'เอกสาร3 สรุปหน่วยงาน',widths:[6,30,32,12,12,12,14,14,18],rows:excel,merges}};
}


function p4pWholePatientType_(a){const id=String(a&&a.id||'');return /^(PN|NA)_(9|10|11|12|13)$/.test(id)||/^(NA|EMP)_/.test(id);}

function roundP4PReport_(value){return Number(Number(value||0).toFixed(2));}

function toBool_(v){return v===true||String(v).toLowerCase()==='true';}

export {p4pSubmissionOutput_ as submissionOutput,p4pHeadCatalog_ as headCatalog,p4pHeadValidate_ as validateHead,p4pHeadEntryScore_ as headScore,p4pClaimDate_ as claimDate,p4pActualDate_ as actualDate,p4pSortStaffByRoster_ as sortStaff,p4pAutoPer_ as autoPer,p4pSignatureHtml_ as signatureHtml};

const escapeHtml_=(v:any)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

function p4pWorkerNames_(details,group){return [...new Set(details.filter(x=>x.name&&p4pGroup_(x)===group).map(x=>String(x.name).trim()))];}
function p4pActivityNames_(details,a){if(p4pRnService_(a)){const rn=details.filter(x=>x.name&&p4pGroup_(x)==='RN'&&!/^HW\b|^ประชุมวิชาการ/i.test(String(x.role||'')));const selected=['S28','S29','S30'].includes(a.id)?(rn.some(x=>String(x.role).trim()==='ทำจำหน่าย')?rn.filter(x=>String(x.role).trim()==='ทำจำหน่าย'):rn.filter(x=>/Incharge/i.test(String(x.role)))):rn;return [...new Set(selected.map(x=>String(x.name).trim()))];}return p4pWorkerNames_(details,a?.group||'RN');}
function p4pActivityDivisor_(details,a){if(a?.auto==='bedcare')return [...new Set(['PN','NA','EMP'].flatMap(g=>p4pWorkerNames_(details,g)))].length;if(a?.group==='PN'&&/^type[123]$/.test(a.auto)||a?.group==='NA'&&/^type[123]$/.test(a.auto))return [...new Set(p4pWorkerNames_(details,'PN').concat(p4pWorkerNames_(details,'NA')))].length;return p4pActivityNames_(details,a).length;}
function p4pRnService_(a){return !!a&&a.category==='ด้านบริการ'&&(a.group==='RN'||/^S\d+$/.test(String(a.id||'')));}
export {p4pActivityNames_ as activityNames,p4pActivityDivisor_ as activityDivisor,p4pRnService_ as rnService,p4pWholePatientType_ as wholePatientType};
